"""###**Training the Quantile Regression Models**

In the study, we considered two models:

- Recurrent Neural Network with LSTM cells

 - A Feedforward Neural Network with 1-Dimensional Convolutional Cells (TCN).

"""

def residual_block(x, dilation, n_filters, kernel_size, l2):
    x_in = x
    x = layers.Conv1D(filters=n_filters, kernel_size=kernel_size,
                      dilation_rate=dilation, padding='causal',
                      kernel_regularizer=keras.regularizers.l2(l2))(x)
    x = layers.BatchNormalization(axis=-1)(x)
    x = layers.Activation('relu')(x)
    x = layers.Conv1D(filters=n_filters, kernel_size=kernel_size,
                      dilation_rate=dilation, padding='causal',
                      kernel_regularizer=keras.regularizers.l2(l2))(x)
    x = layers.BatchNormalization(axis=-1)(x)
    x = x + layers.Conv1D(filters=n_filters, kernel_size=1, dilation_rate=1,
                          kernel_regularizer=keras.regularizers.l2(l2))(x_in)
    x = layers.Activation('relu')(x)
    return x

def tcn(P):
    x_in = layers.Input(shape=(P['time_steps_in'], P['n_vars']))
    x = x_in
    for d in P['dilations']:
        x = residual_block(x, dilation=d, n_filters=P['n_filters'],
                           kernel_size=P['kernel_size'], l2=P['l2'])
    x = layers.GlobalAveragePooling1D()(x)
    x = layers.Dense(P['time_steps_out']*len(P['quantiles']),
                     kernel_regularizer=keras.regularizers.l2(P['l2']))(x)
    out_quantiles = tf.reshape(x, (-1, P['time_steps_out'], len(P['quantiles'])))
    model = keras.Model(inputs=[x_in], outputs=[out_quantiles])
    # model.summary()
    return model

def LSTM_stateful(P):
    # Since we use return_sequences=True, we must specify batch shape explicitly
    x_in = layers.Input(batch_shape=(P['batch_size'], P['time_steps_in'], P['n_vars']))
    x = x_in
    if P['n_layers'] > 1:
        for i in range(P['n_layers']-1):
            x = layers.LSTM(P['units'],
                            stateful=True,
                            return_sequences=True,
                            kernel_regularizer=keras.regularizers.l2(P['l2']))(x)
    x = layers.LSTM(P['units'],
                    stateful=True,
                    kernel_regularizer=keras.regularizers.l2(P['l2']))(x)
    x = layers.Dense(P['time_steps_out']*len(P['quantiles']), kernel_regularizer=keras.regularizers.l2(P['l2']))(x)
    out_quantiles = tf.reshape(x, (-1, P['time_steps_out'], len(P['quantiles'])))
    model = keras.Model(inputs=[x_in], outputs=[out_quantiles])
    # model.summary()
    return model

def _pin_loss(labels, pred, quantiles):
    loss = []
    for i,q in enumerate(quantiles):
        error = tf.subtract(labels,pred[:,:,i])
        loss_q = tf.reduce_mean(tf.maximum(q*error,(q-1)*error))
        loss.append(loss_q)
    L = tf.convert_to_tensor(loss)
    total_loss = tf.reduce_mean(L)
    return total_loss

def pi_cov(y_true, y_pred):
    """Compute average coverage of prediction intervals"""
    coverage = tf.reduce_mean(
        tf.cast((y_true >= y_pred[:,:,0])&(y_true <= y_pred[:,:,2]), tf.float32))
    return coverage

def pi_len(y_true, y_pred):
    """Compute length of prediction intervals"""
    avg_length = tf.reduce_mean(tf.abs(y_pred[:,:,2] - y_pred[:,:,0]))
    avg_length = avg_length/(tf.reduce_max(y_true) - tf.reduce_min(y_true))
    return  avg_length

class keras_model():
    def __init__(self, P):
        self.P = P
        if P['model_type'] == 'lstm':
            self.model = LSTM_stateful(P)
        elif P['model_type'] == 'tcn':
            self.model = tcn(P)
        else:
            raise ValueError("model_type must be 'lstm' or 'tcn'")
    def fit(self, train_x, train_y, val_x, val_y, epochs=100, patience=10, verbose=0):
        # Create a tf Dataset.
        tf_train_data = tf.data.Dataset.from_tensor_slices((train_x, train_y)).repeat().batch(self.P['batch_size'])
        val_data = tf.data.Dataset.from_tensor_slices((val_x, val_y)).repeat().batch(self.P['batch_size'])
        # Since we use repeat(), we must specify the number of times we draw a bach in an epoch
        TRAIN_STEPS = int(np.ceil(train_x.shape[0]/self.P['batch_size']))
        VAL_STEPS = int(np.ceil(val_x.shape[0]/self.P['batch_size']))
        if self.P['regression'] == 'quantile':
            self.model.compile(optimizer='adam',
                    loss=[lambda y_true, y_pred: _pin_loss(y_true, y_pred, self.P['quantiles'])],
                    metrics=[pi_cov, pi_len])
        elif self.P['regression'] == 'linear':
            self.model.compile(optimizer='adam',
                    loss='mse')
        es = tf.keras.callbacks.EarlyStopping(
            monitor="val_loss",
            patience=patience,
        )
        history = self.model.fit(tf_train_data,
                       validation_data=val_data,
                       epochs=epochs,
                       steps_per_epoch=TRAIN_STEPS,
                       validation_steps=VAL_STEPS,
                       callbacks=[es],
                       verbose=verbose)
        return history

    def transform(self, data_x):
        tf_data = tf.data.Dataset.from_tensor_slices(data_x).repeat().batch(self.P['batch_size'])
        it = iter(tf_data)
        n_steps = int(np.ceil(data_x.shape[0]/self.P['batch_size']))
        preds =[]
        for _ in range(n_steps):
            batch = next(it)
            preds.append(self.model(batch))
        preds = np.concatenate(preds, axis=0)
        preds = preds[:data_x.shape[0],:,:]
        return preds

class rf_model():
    def __init__(self, P):
        self.P = P
        self.model = RandomForestRegressor(n_estimators=P['n_trees'])
    def fit(self, train_x, train_y, val_x=None, val_y=None):
        self.model.fit(train_x.reshape(train_x.shape[0],-1), train_y)
    def transform(self, data_x, percentile=90):
        data_x = data_x.reshape(data_x.shape[0], -1)
        prediction_int = np.zeros((data_x.shape[0], self.P['time_steps_out'], 3))
        preds = []
        for tree in self.model.estimators_:
            preds.append(tree.predict(data_x))
        preds = np.stack(preds, axis=-1)
        prediction_int[:,:,0] = np.percentile(preds, self.P['quantiles'][0]*100, axis=-1)
        prediction_int[:,:,1] = np.percentile(preds, self.P['quantiles'][1]*100, axis=-1)
        prediction_int[:,:,2] = np.percentile(preds, self.P['quantiles'][2]*100, axis=-1)
        return prediction_int

def regression_model(P):
    if P['model_type'] in ['lstm', 'tcn']:
        return keras_model(P)
    elif P['model_type'] == 'rf':
        return rf_model(P)
    else:
        raise ValueError("model_type must be 'lstm', 'tcn', or 'rf'")

"""**Specify Several Configuration Hyperparameters and store them in a dictionary, and The Utilities**"""

# General hyperparams
B = 3                       # number of ensembles
alpha = 0.1                 # confidence level
quantiles = [alpha/2,       # quantiles to predict
             0.5,
             1-(alpha/2)]

# rf hyperparams
n_trees = 20                # number of trees in each rf model

# lstm tcn only
regression = 'quantile'     # options: {'quantile', 'linear'}. If 'linear', just set one quantile
l2_lambda = 1e-4            # weight of l2 regularization in the lstm and tcn models
batch_size = 32             # size of batches using to train the lstm and tcn models

# lstm hyperparams
units = 256                 # number of units in each lstm layer
n_layers = 3                # number of lstm layers in the model

# tcn hyperparams
dilations = [1, 2, 4, 8]       # dilation rate of the Conv1D layers
n_filters = 256             # filters in each Conv1D layer
kernel_size = 7             # kernel size in each ConvID layer

# Store the configuration in a dictionary
P = {'B':B, 'alpha':alpha, 'quantiles':quantiles,
     'n_trees':n_trees,
     'regression':regression,'l2':l2_lambda, 'batch_size':batch_size,
     'units':units,'n_layers':n_layers,
     'dilations':dilations, 'n_filters':n_filters, 'kernel_size':kernel_size}

# Update configuration dict
P['time_steps_in'] = test_x.shape[1]
P['n_vars'] = test_x.shape[2]
P['time_steps_out'] = test_y.shape[1]

print(f"time_steps_in: {test_x.shape[1]}, n_vars: {test_x.shape[2]}, time_steps_out: {test_y.shape[1]}")

def compute_coverage_len(y_test, y_lower, y_upper, verbose=False, eta=30, mu=0.9):
    """Compute average coverage and length of prediction intervals"""
    in_the_range = np.sum((y_test >= y_lower) & (y_test <= y_upper))
    coverage = in_the_range / np.prod(y_test.shape)
    avg_length = np.mean(abs(y_upper - y_lower))
    avg_length = avg_length/(y_test.max()-y_test.min())
    cwc = (1-avg_length)*np.exp(-eta*(coverage-mu)**2)
    if verbose==True:
        print(f"PI coverage: {coverage*100:.1f}%, PI avg. length: {avg_length:.3f}, CWC: {cwc:.3f}")
    else:
        return coverage, avg_length, cwc

def asym_nonconformity(label, low, high):
    """Compute the asymetric conformity score"""
    error_high = label - high
    error_low = low - label
    return error_low, error_high

def plot_PIs(true, pred_mean, PI_low=None, PI_hi=None,
             conf_PI_low=None, conf_PI_hi=None,
             x_lims=None, scaler=None, title=None,
             label_pi=None):

    if scaler:
        true = scaler.inverse_transform_y(true)
        pred_mean = scaler.inverse_transform_y(pred_mean)
    true = true.flatten()
    pred_mean = pred_mean.flatten()

    plt.set_cmap("tab10")
    plt.cm.tab20(0)
    plt.figure(figsize=(12, 3.5))
    plt.plot(np.arange(true.shape[0]), true, label='True', color='k')
    plt.plot(pred_mean, label='Pred', color=plt.cm.tab10(1))

    if conf_PI_low is not None:

        if scaler:
            conf_PI_low = scaler.inverse_transform_y(conf_PI_low)
            conf_PI_hi = scaler.inverse_transform_y(conf_PI_hi)
            PI_low = scaler.inverse_transform_y(PI_low)
            PI_hi = scaler.inverse_transform_y(PI_hi)
        conf_PI_hi = conf_PI_hi.flatten()
        conf_PI_low = conf_PI_low.flatten()
        PI_hi = PI_hi.flatten()
        PI_low = PI_low.flatten()
        plt.fill_between(np.arange(true.shape[0]), conf_PI_low, conf_PI_hi, alpha=0.3, label='Conformalized')
        plt.plot(PI_low, label='original', color=plt.cm.tab10(0), linestyle='dashed')
        plt.plot(PI_hi, color=plt.cm.tab10(0), linestyle='dashed')

    if (conf_PI_low is None) and (PI_low is not None):
        if scaler:
            PI_low = scaler.inverse_transform_y(PI_low)
            PI_hi = scaler.inverse_transform_y(PI_hi)

        if label_pi is None:
            label_pi = 'PI'
        PI_hi = PI_hi.flatten()
        PI_low = PI_low.flatten()
        plt.fill_between(np.arange(true.shape[0]), PI_low, PI_hi, alpha=0.3, label=label_pi)

    if x_lims is not None:
        plt.xlim(x_lims)
    plt.legend(loc='upper right')
    plt.grid()

    if title is not None:
        plt.title(title)

    plt.show()

def plot_history(history):
    hist_dict = history.history
    plt.set_cmap("tab10")
    plt.cm.tab20(0)
    fig, axs = plt.subplots(1,3, figsize=(9,2.5))

    axs[0].plot(hist_dict['loss'], label='tr_loss', color='k')
    axs[0].plot(hist_dict['val_loss'], label='val_loss', color='k', linestyle='dashed')
    axs[0].legend()

    axs[1].axhline(y=0.9, color='r', linestyle='-')
    axs[1].plot(hist_dict['pi_cov'], label='tr_pi_cov', color=plt.cm.tab10(0))
    axs[1].plot(hist_dict['val_pi_cov'], label='val_pi_cov', color=plt.cm.tab10(0), linestyle='dashed')
    axs[1].legend(loc='lower right')

    axs[2].plot(hist_dict['pi_len'], label='tr_pi_len', color=plt.cm.tab10(1))
    axs[2].plot(hist_dict['val_pi_len'], label='val_pi_len', color=plt.cm.tab10(1), linestyle='dashed')
    axs[2].legend()

    plt.tight_layout()
    plt.show()

"""##**Compute the Intervals with the EnCQR Method**

The Method returns two intervals:

- the PI computed by the ensemble of QR models
- the conformalized PI

###**EnCQR Model**
"""

def EnCQR(train_data, val_x, val_y, test_x, test_y, P):
    index = np.arange(P['B'])
    s = P['time_steps_out']
    # dict containing LOO predictions
    dct_lo = {}
    dct_hi = {}
    for key in index:
      dct_lo['pred_%s' % key] = []
      dct_hi['pred_%s' % key] = []
    # training a model for each sub set Sb
    ensemble_models = []
    for b in range(P['B']):
        f_hat_b = regression_model(P)
        f_hat_b.fit(train_data[index[b]][0], train_data[index[b]][1], val_x, val_y)
        ensemble_models.append(f_hat_b)
        # Leave-one-out predictions for each Sb
        indx_LOO = index[np.arange(len(index))!=b]
        for i in range(len(indx_LOO)):
            pred = f_hat_b.transform(train_data[indx_LOO[i]][0])
            dct_lo['pred_%s' %indx_LOO[i]].append(pred[:,:,0])
            dct_hi['pred_%s' %indx_LOO[i]].append(pred[:,:,2])
    f_hat_b_agg_low  = np.zeros((train_data[index[0]][0].shape[0], P['time_steps_out'], P['B']))
    f_hat_b_agg_high = np.zeros((train_data[index[0]][0].shape[0], P['time_steps_out'], P['B']))
    for b in range(P['B']):
        f_hat_b_agg_low[:,:,b] = np.mean(dct_lo['pred_%s' %b],axis=0)
        f_hat_b_agg_high[:,:,b] = np.mean(dct_hi['pred_%s' %b],axis=0)
    # residuals on the training data
    epsilon_low = []
    epsilon_hi=[]
    for b in range(P['B']):
        e_low, e_high = asym_nonconformity(label=train_data[b][1],
                                                  low=f_hat_b_agg_low[:,:,b],
                                                  high=f_hat_b_agg_high[:,:,b])
        epsilon_low.append(e_low)
        epsilon_hi.append(e_high)
    epsilon_low = np.array(epsilon_low).flatten()
    epsilon_hi = np.array(epsilon_hi).flatten()
    # Construct PIs for test data
    f_hat_t_batch = np.zeros((test_y.shape[0], test_y.shape[1], 3, P['B']))
    for b, model_b in enumerate(ensemble_models):
        f_hat_t_batch[:,:,:,b] = model_b.transform(test_x)
    PI  = np.mean(f_hat_t_batch,  axis=-1)

    # Conformalize prediction intervals on the test data
    conf_PI = np.zeros((test_y.shape[0], test_y.shape[1], 3))
    conf_PI[:,:,1] = PI[:,:,1]
    for i in range(test_y.shape[0]):
        e_quantile_lo = np.quantile(epsilon_low, 1-P['alpha']/2)
        e_quantile_hi = np.quantile(epsilon_hi, 1-P['alpha']/2)
        conf_PI[i,:,0] = PI[i,:,0] - e_quantile_lo
        conf_PI[i,:,2] = PI[i,:,2] + e_quantile_hi

        # update epsilon with the last s steps
        e_lo, e_hi = asym_nonconformity(label=test_y[i,:],
                                                low=PI[i,:,0],
                                                high=PI[i,:,2])
        epsilon_low = np.delete(epsilon_low,slice(0,s,1))
        epsilon_hi = np.delete(epsilon_hi,slice(0,s,1))
        epsilon_low = np.append(epsilon_low, e_lo)
        epsilon_hi = np.append(epsilon_hi, e_hi)
    return PI, conf_PI

