"""###**Echo State Network - Quantile Regression : ESN-QR**

**Utilities**
"""

def compute_coverage_len(y_test, y_lower, y_upper):
    """Compute average coverage and length of prediction intervals"""
    coverage = np.mean((y_test >= y_lower) & (y_test <= y_upper))
    avg_length = np.mean(abs(y_upper - y_lower))
    avg_length = avg_length/(y_test.max()-y_test.min())
    return coverage, avg_length

def plot_forecast(predictive, Y, diffXte, diffYte, name, length=None, n=2):
    mean_index = int(predictive.shape[1]/2)
    q_low, mean, q_hi = predictive[:,n].cpu().numpy(), predictive[:,mean_index].cpu().numpy(), predictive[:,-n].cpu().numpy()
    fig = plt.figure(figsize=(15, 5))
    plt.plot((Y.cpu()+diffYte)[:length], label='true value', color='k')
    plt.fill_between(np.arange(mean.shape[0])[:length], (q_low+diffYte)[:length], (q_hi+diffYte)[:length], alpha=0.3, label='0.95 PI')
    plt.plot((mean+diffYte)[:length], label='prediction')
    plt.legend(loc='best')
    plt.grid()
    # Show and save plot
    save_path = f'/content/gdrive/MyDrive/Energy_System_RL_Modelling_Plots/'
    Path(save_path).mkdir(parents=True, exist_ok=True) # create folder if it does not exist
    plt.savefig(f'{save_path}{name}.png')
    plt.show()
    plt.close(fig)
    pass

def check_calibration(predictive, Y, quantiles):
    """It computes the calibration error according to formula (9) of paper https://arxiv.org/pdf/1807.00263.pdf
    """
    if not isinstance(Y, torch.Tensor):
        Y = torch.tensor(Y)
    if not isinstance(predictive, torch.Tensor):
        predictive = torch.tensor(predictive)
    # Compute predicted CDF
    predicted_cdf = np.mean(
        Y.unsqueeze(dim=1).cpu().numpy() <= predictive.cpu().numpy(), axis=0)
    # Compute calibration error
    w = 1
    cal_error = np.sum(w*(predicted_cdf-quantiles)**2)
    return cal_error, predicted_cdf

def calibrate(predictive, predictive2, Y, Y2, quantiles, folder, plot=False):
    """Function that computes the calibration error on the test dataset,
    train a calibrator on the evaluation dataset and check again the
    error on test dataset (or vice versa)"""
    # Check calibration on first dataset
    cal_error, unc_cdf = check_calibration(predictive, Y, quantiles)
    # Calibrate on second dataset
    # Fit calibrator
    predicted_cdf = np.mean(Y2.unsqueeze(dim=1).cpu().numpy() <= predictive2.cpu().numpy(), axis=0)
    isotonic = IsotonicRegression(out_of_bounds='clip')
    isotonic.fit(quantiles, predicted_cdf)
    # Check again calibration on first dataset
    new_quantiles = isotonic.transform(quantiles)
    new_cal_error, cal_cdf = check_calibration(predictive, Y, new_quantiles)
    # Plot calibration graph
    if plot:
        ax = plt.figure(figsize=(6, 6))
        ax = plt.gca()
        ax.plot(quantiles, unc_cdf, '-x', color='purple', label='Uncalibrated')
        ax.plot(new_quantiles, cal_cdf, '-+', color='red', label='Calibrated')
        ax.plot([0,1],[0,1],'--', color='grey', label='Perfect calibration')
        ax.set_xlabel('Predicted', fontsize=17)
        ax.set_ylabel('Empirical', fontsize=17)
        ax.set_title('Predicted CDF vs Empirical CDF', fontsize=17)
        ax.legend(fontsize=10)
        save_path = './results/plots/' + folder + '/'
        Path(save_path).mkdir(parents=True, exist_ok=True) # create folder if it does not exist
        plt.savefig(f'{save_path}' + 'calibration' + '.png')
        plt.clf()
    return cal_error, new_cal_error, new_quantiles

def eval_crps(quantiles, tau, y):
    """It computes a discrete version of the CRPS so to use it to evaluate quantile
    regression"""
    q = np.asarray(quantiles)
    H = np.heaviside(tau-y, 0)
    dx = np.asarray([tau[:,i+1] - tau[:,i] for i in range(tau.shape[1]-1)]).T
    crps = np.mean(np.sum(dx*((q-H)[:,1:]**2), 1))
    return crps

def quantile_loss(quantiles, output, target):
    losses = []
    for i, q in enumerate(quantiles):
        error = target-output[:,i]
        losses.append(torch.max(q*error, (q-1)*error))
    loss = torch.mean(torch.sum(torch.stack(losses), dim=-1))
    return loss

def to_torch(array, device):
    """Transform numpy arrays to torch tensors and move them to `device`"""
    dtype = 'float32'
    array = array.astype(dtype)
    return from_numpy(array).to(device)

def NRMSE(y_true, y_pred):
    """ Normalized Root Mean Squared Error """
    y_var = np.var(y_true)
    return np.sqrt(mean_squared_error(y_true, y_pred) / y_var)

class EarlyStopping:
    """Early stops the training if validation loss doesn't improve after a given patience.
    Based on https://github.com/Bjarten/early-stopping-pytorch"""
    def __init__(self, patience=10, verbose=False, delta=0, path='/content/checkpoints/QR/', trace_func=print):
        self.patience = patience
        self.verbose = verbose
        self.counter = 0
        self.best_score = None
        self.early_stop = False
        self.val_loss_min = np.Inf
        self.delta = delta
        self.path = path
        self.trace_func = trace_func
    def __call__(self, val_loss, model):
        score = -val_loss
        if self.best_score is None:
            self.best_score = score
            self.save_checkpoint(val_loss, model)
        elif score < self.best_score + self.delta:
            self.counter += 1
            if self.verbose:
                self.trace_func(f'EarlyStopping counter: {self.counter} out of {self.patience}')
            if self.counter >= self.patience:
                self.early_stop = True
        else:
            self.best_score = score
            self.save_checkpoint(val_loss, model)
            self.counter = 0

    def save_checkpoint(self, val_loss, model):
        '''Saves model when validation loss decrease.'''
        if self.verbose:
            self.trace_func(f'Validation loss decreased ({self.val_loss_min:.6f} --> {val_loss:.6f}).  Saving model ...')
        Path(self.path).mkdir(parents=True, exist_ok=True) # create folder if it does not exist
        torch.save(model.state_dict(), self.path + "checkpoint.pt")
        #torch.save(model.state_dict(), self.path)
        self.val_loss_min = val_loss

"""**Training and Prediction Functions**"""

def train_QR(model, X, Y, X_val, Y_val, lr, epochs, quantiles):
    torch_optimizer = torch.optim.Adam(model.parameters(), lr=lr, weight_decay=1e-4)
    # initialize the early_stopping object
    #checkpoint_path = '/content/'
    checkpoint_path = "/content/checkpoints/QR/"
    early_stopping = EarlyStopping(patience=10, verbose=False, path=checkpoint_path)

    start_time = process_time()
    with trange(epochs) as t:
        for epoch in t:
            model.train()
            torch_optimizer.zero_grad()
            loss = quantile_loss(quantiles, model(X), Y)
            loss.backward()
            torch_optimizer.step()
            # display progress bar
            t.set_description(f"Epoch {epoch+1}")
            t.set_postfix({"loss":float(loss / Y.shape[0])})
            # Early stopping
            model.eval()
            valid_loss = quantile_loss(quantiles, model(X_val), Y_val).item()
            # early_stopping needs the validation loss to check if it has decresed,
            # and if it has, it will make a checkpoint of the current model
            early_stopping(valid_loss, model)
            if early_stopping.early_stop:
                print("Early stopping")
                break
    train_time = process_time() - start_time

    # load the last checkpoint with the best model
    model.load_state_dict(torch.load(checkpoint_path + "checkpoint.pt"))
    diagnostics = {
        "train_time": train_time,
        "final_loss": float((loss / Y.shape[0]).detach().cpu())
    }
    return diagnostics

def pred_QR(model, X_val, Y_val, X_test, Y_test, plot, sweep, diagnostics, quantiles):
    model.eval()
    # Use validation set for hyperparameters tuning
    if sweep:
        X, Y = X_val, Y_val
        X2, Y2 = X_test, Y_test
    else:
        X, Y = X_test, Y_test
        X2, Y2 = X_val, Y_val
    # Perform inference
    start_time = process_time()
    predictive = model(X).detach().squeeze()
    inference_time = process_time() - start_time
    diagnostics["inference_time"] = inference_time
    # Compute calibration error
    predictive2 = model(X2).detach().squeeze()
    # Calibrate
    # calibration doesn't make sense for QR
    cal_error, new_cal_error, new_quantiles = calibrate(
        predictive, predictive2, Y, Y2, quantiles, folder="q_regr", plot=plot)
    diagnostics["cal_error"] = cal_error
    diagnostics["new_cal_error"] = new_cal_error    # it does not refer to same quantiles
    diagnostics["quantiles"] = quantiles
    diagnostics["new_quantiles"] = new_quantiles
    # Width of 0.95 quantiles
    q_low = predictive[:,2].cpu().numpy()
    q_hi = predictive[:,-2].cpu().numpy()
    diagnostics["width"] = np.mean(q_hi - q_low)
    # After calibration it does not refer to same quantiles
    diagnostics["new_width"] = float('nan')
    # Check coverage with 95% quantiles
    if predictive.dim() > 1:
        coverage, avg_length = compute_coverage_len(Y.cpu().numpy(), q_low, q_hi)
        diagnostics["coverage"] = coverage
        diagnostics["avg_length"] = avg_length
        # After calibration it does not refer to same quantiles
        diagnostics["new_coverage"] = float('nan')
        diagnostics["new_avg_length"] = float('nan')
    # Mean Squared Error wrt the median
    mean_index = int(predictive.shape[1]/2)
    median = predictive[:,mean_index].cpu().numpy()
    mse = np.mean((median-Y.cpu().numpy())**2)
    diagnostics["mse"] = mse
    # After calibration it does not refer to the median
    diagnostics["new_mse"] = float('nan')
    # Continuous ranked probability score
    crps = eval_crps(quantiles, predictive.cpu().numpy(), Y.unsqueeze(dim=1).cpu().numpy())
    diagnostics["crps"] = crps
    # After calibration it does not refer to same quantiles
    diagnostics["new_crps"] = float('nan')
    return predictive, diagnostics

"""###**ESN Model**"""

class ESN(object):
    def __init__(self, n_internal_units = 100, spectral_radius = 0.9,
                 connectivity = 0.5, input_scaling = 0.5, input_shift = 0.0,
                 teacher_scaling = 0.5, teacher_shift = 0.0, feedback_scaling = 0.01,
                 noise_level = 0.01):
        # Initialize attributes
        self._n_internal_units = n_internal_units
        self._spectral_radius = spectral_radius
        self._connectivity = connectivity
        self._input_scaling = input_scaling
        self._input_shift = input_shift
        self._teacher_scaling = teacher_scaling
        self._teacher_shift = teacher_shift
        self._feedback_scaling = feedback_scaling
        self._noise_level = noise_level
        self._dim_output = None
        # The weights will be set later, when data is provided
        self._input_weights = None
        self._feedback_weights = None
        # Regression method and embedding method.
        # Initialized to None for now. Will be set during 'fit'.
        self._regression_method = None
        self._embedding_method = None
        # Generate internal weights
        self._internal_weights = self._initialize_internal_weights(n_internal_units, connectivity, spectral_radius)

    def fit(self, Xtr, Ytr, n_drop = 100, regression_method = 'linear', regression_parameters = None, embedding = 'identity', n_dim = 3, embedding_parameters = None):
        _,_ = self._fit_transform(Xtr = Xtr, Ytr = Ytr, n_drop = n_drop, regression_method = regression_method, regression_parameters = regression_parameters, embedding = embedding, n_dim = n_dim, embedding_parameters = embedding_parameters)
        return

    def _fit_transform(self, Xtr, Ytr, n_drop = 100, regression_method = 'linear', regression_parameters = None, embedding = 'identity', n_dim = 3, embedding_parameters = None):
        n_data, dim_data = Xtr.shape
        _, dim_output = Ytr.shape
        self._dim_output = dim_output
        # If this is the first time the network is tuned, set the input and feedback weights.
        # The weights are dense and uniformly distributed in [-1.0, 1.0]
        if (self._input_weights is None):
            self._input_weights = 2.0*np.random.rand(self._n_internal_units, dim_data) - 1.0
        if (self._feedback_weights is None):
            self._feedback_weights = 2.0*np.random.rand(self._n_internal_units, dim_output) - 1.0
        # Initialize regression method
        if (regression_method == 'nusvr'):
            # NuSVR, RBF kernel
            C, nu, gamma = regression_parameters
            self._regression_method = NuSVR(C = C, nu = nu, gamma = gamma)
        elif (regression_method == 'linsvr'):
            # NuSVR, linear kernel
            C = regression_parameters[0]
            nu = regression_parameters[1]
            self._regression_method = NuSVR(C = C, nu = nu, kernel='linear')
        elif (regression_method == 'enet'):
            # Elastic net
            alpha, l1_ratio = regression_parameters
            self._regression_method = ElasticNet(alpha = alpha, l1_ratio = l1_ratio)
        elif (regression_method == 'ridge'):
            # Ridge regression
            self._regression_method = Ridge(alpha = regression_parameters)
        elif (regression_method == 'lasso'):
            # LASSO
            self._regression_method = Lasso(alpha = regression_parameters)
        else:
            # Use canonical linear regression
            self._regression_method = LinearRegression()
        # Initialize embedding method
        if (embedding == 'identity'):
            self._embedding_dimensions = self._n_internal_units
        else:
            self._embedding_dimensions = n_dim
            if (embedding == 'kpca'):
                # Kernel PCA with RBF kernel
                self._embedding_method = KernelPCA(n_components = n_dim, kernel = 'rbf', gamma = embedding_parameters)
            elif (embedding == 'pca'):
                # PCA
                self._embedding_method = PCA(n_components = n_dim)
            else:
                raise(ValueError, "Unknown embedding method")
        # Calculate states/embedded states.
        # Note: If the embedding is 'identity', embedded states will be equal to the states.
        states, embedded_states,_ = self._compute_state_matrix(X = Xtr, Y = Ytr, n_drop = n_drop)
        # Train output
        self._regression_method.fit(
                np.concatenate((
                        embedded_states,
                        self._scaleshift(Xtr[n_drop:,:], self._input_scaling, self._input_shift)), axis=1),
                self._scaleshift(Ytr[n_drop:,:], self._teacher_scaling, self._teacher_shift))
        return states, embedded_states

    def predict(self, X, Y = None, n_drop = 100, error_function = NRMSE):
        Yhat, error, _, _ = self._predict_transform(X = X, Y = Y, n_drop = n_drop, error_function = error_function)
        return Yhat, error

    def _predict_transform(self, X, Y = None, n_drop = 100, error_function = NRMSE):
        # Predict outputs
        states,embedded_states,Yhat = self._compute_state_matrix(X = X, n_drop = n_drop)
        # Revert scale and shift
        Yhat = self._uscaleshift(Yhat, self._teacher_scaling, self._teacher_shift)
        # Compute error if ground truth is provided
        if (Y is not None):
            error = error_function(Y[n_drop:,:], Yhat)
        return Yhat, error, states, embedded_states

    def _compute_state_matrix(self, X, Y = None, n_drop = 100):
        n_data, _ = X.shape
        # Initial values
        previous_state = np.zeros((1, self._n_internal_units), dtype=float)
        previous_output = np.zeros((1, self._dim_output), dtype=float)
        # Storage
        state_matrix = np.empty((n_data - n_drop, self._n_internal_units), dtype=float)
        embedded_states = np.empty((n_data - n_drop, self._embedding_dimensions), dtype=float)
        outputs = np.empty((n_data - n_drop, self._dim_output), dtype=float)
        for i in range(n_data):
            # Process inputs
            previous_state = np.atleast_2d(previous_state)
            current_input = np.atleast_2d(self._scaleshift(X[i, :], self._input_scaling, self._input_shift))
            feedback = self._feedback_scaling*np.atleast_2d(previous_output)
            # Calculate state. Add noise and apply nonlinearity.
            state_before_tanh = self._internal_weights.dot(previous_state.T) + self._input_weights.dot(current_input.T) + self._feedback_weights.dot(feedback.T)
            state_before_tanh += np.random.rand(self._n_internal_units, 1)*self._noise_level
            previous_state = np.tanh(state_before_tanh).T
            # Embed data and perform regression if applicable.
            if (Y is not None):
                # If we are training, the previous output should be a scaled and shifted version of the ground truth.
                previous_output = self._scaleshift(Y[i, :], self._teacher_scaling, self._teacher_shift)
            else:
                # Should the data be embedded?
                if (self._embedding_method is not None):
                    current_embedding = self._embedding_method.transform(previous_state)
                else:
                    current_embedding = previous_state
                # Perform regression
                previous_output = self._regression_method.predict(np.concatenate((current_embedding, current_input), axis=1))
            # Store everything after the dropout period
            if (i > n_drop - 1):
                state_matrix[i - n_drop, :] = previous_state.flatten()
                # Only save embedding for test data.
                # In training, we do it after computing the whole state matrix.
                if (Y is None):
                    embedded_states[i - n_drop, :] = current_embedding.flatten()
                outputs[i - n_drop, :] = previous_output.flatten()
        # Now, embed the data if we are in training
        if (Y is not None):
            if (self._embedding_method is not None):
                embedded_states = self._embedding_method.fit_transform(state_matrix)
            else:
                embedded_states = state_matrix
        return state_matrix, embedded_states, outputs

    def _scaleshift(self, x, scale, shift):
        # Scales and shifts x by scale and shift
        return (x*scale + shift)

    def _uscaleshift(self, x, scale, shift):
        # Reverts the scale and shift applied by _scaleshift
        return ( (x - shift)/float(scale) )

    def _initialize_internal_weights(self, n_internal_units, connectivity, spectral_radius):
        # The eigs function might not converge. Attempt until it does.
        convergence = False
        while (not convergence):
            # Generate sparse, uniformly distributed weights.
            internal_weights = sparse.rand(n_internal_units, n_internal_units, density=connectivity).todense()
            # Ensure that the nonzero values are uniformly distributed in [-0.5, 0.5]
            internal_weights[np.where(internal_weights > 0)] -= 0.5
            try:
                # Get the largest eigenvalue
                w,_ = slinalg.eigs(internal_weights, k=1, which='LM')
                convergence = True
            except:
                continue
        # Adjust the spectral radius.
        internal_weights /= np.abs(w)/spectral_radius
        return np.array(internal_weights)

def run_from_config_return_states(Xtr, Ytr, Xte, Yte, config, validation=False, Xval=None, Yval=None):
    # Instantiate ESN object
    esn = ESN(n_internal_units = config['n_internal_units'],
              spectral_radius = config['spectral_radius'],
              connectivity = config['connectivity'],
              input_scaling = config['input_scaling'],
              input_shift = config['input_shift'],
              teacher_scaling = config['teacher_scaling'],
              teacher_shift = config['teacher_shift'],
              feedback_scaling = config['feedback_scaling'],
              noise_level = config['noise_level'])
    # Get parameters
    n_drop = config['n_drop']
    regression_method = config['regression_method']
    regression_parameters = config['regression_parameters']
    embedding = config['embedding']
    n_dim = config['n_dim']
    embedding_parameters = config['embedding_parameters']
    # Fit and predict
    train_states, train_embedding = esn._fit_transform(Xtr, Ytr, n_drop = n_drop, regression_method = regression_method,
                                                       regression_parameters = regression_parameters,
                                                       embedding = embedding, n_dim = n_dim,
                                                       embedding_parameters = embedding_parameters)

    Yhat, error, test_states, test_embedding = esn._predict_transform(Xte, Yte, n_drop=n_drop)

    if validation:
        _, _, val_states, val_embedding = esn._predict_transform(Xval, Yval, n_drop=n_drop)
        return Yhat, error, train_states, train_embedding, val_states, val_embedding, test_states, test_embedding
    else:
        return Yhat, error, train_states, train_embedding, test_states, test_embedding

