class TorchModel(torch.nn.Module):
    """Deterministic model"""
    def __init__(self, widths, activation, dropout=False, p=0.0, quantiles=None):
        super().__init__()
        self.layers = torch.nn.ModuleList()
        if activation == "tanh":
            a = torch.nn.Tanh()
        elif activation == "relu":
            a = torch.nn.ReLU()
        else:
            raise ValueError(f"{activation} not defined.")
